/* ---------------- Utils ---------------- */
function uid(prefix) {
  return prefix + "_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}
function genCode(existingCodes) {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let code;
  do {
    let s = "";
    for (let i = 0; i < 5; i++) s += chars[Math.floor(Math.random() * chars.length)];
    code = "VD-" + s;
  } while (existingCodes.includes(code));
  return code;
}
function pad2(n) { return String(n).padStart(2, "0"); }
function toDateStr(d) { return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`; }
function todayStr() { return toDateStr(new Date()); }
function addDays(dateStr, n) {
  const d = new Date(dateStr + "T00:00:00");
  d.setDate(d.getDate() + n);
  return toDateStr(d);
}
function dowOf(dateStr) { return new Date(dateStr + "T00:00:00").getDay(); }
function timeToMin(t) { const [h, m] = t.split(":").map(Number); return h * 60 + m; }
function minToTime(m) { return `${pad2(Math.floor(m / 60))}:${pad2(m % 60)}`; }
function fmtDateHuman(dateStr) {
  if (!dateStr) return "";
  const d = new Date(dateStr + "T00:00:00");
  return d.toLocaleDateString("es-BO", { weekday: "long", day: "numeric", month: "long", year: "numeric" });
}
function fmtDateShort(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  return d.toLocaleDateString("es-BO", { day: "2-digit", month: "2-digit", year: "numeric" });
}
function hoursUntil(dateStr, timeStr) {
  const target = new Date(`${dateStr}T${timeStr}:00`);
  return (target.getTime() - Date.now()) / (1000 * 60 * 60);
}
function waLink(phone, text) {
  const clean = (phone || "").replace(/\D/g, "");
  const full = clean.startsWith("591") ? clean : "591" + clean;
  return `https://wa.me/${full}${text ? "?text=" + encodeURIComponent(text) : ""}`;
}
function maskPhone(phone) {
  const clean = (phone || "").replace(/\D/g, "");
  if (clean.length <= 4) return "••••";
  return "•••• " + clean.slice(-4);
}

function emptyDays() {
  return Object.fromEntries([0, 1, 2, 3, 4, 5, 6].map((i) => [i, { enabled: false, start: "08:00", end: "17:00", breakStart: "", breakEnd: "" }]));
}
function normalizeProfiles(schedule) {
  if (!schedule) {
    return [{ id: uid("sch"), name: "Horario principal", active: true, days: emptyDays(), blockedDates: [], specialDates: {} }];
  }
  if (schedule.profiles && schedule.profiles.length) return schedule.profiles;
  if (schedule.days) {
    return [{ id: uid("sch"), name: "Horario principal", active: true, days: schedule.days, blockedDates: schedule.blockedDates || [], specialDates: schedule.specialDates || {} }];
  }
  const days = {};
  for (let i = 0; i <= 6; i++) {
    const enabled = (schedule.workDays || []).includes(i);
    days[i] = enabled
      ? { enabled: true, start: schedule.startTime, end: schedule.endTime, breakStart: schedule.breakStart, breakEnd: schedule.breakEnd }
      : { enabled: false, start: "", end: "", breakStart: "", breakEnd: "" };
  }
  return [{ id: uid("sch"), name: "Horario principal", active: true, days, blockedDates: schedule.blockedDates || [], specialDates: schedule.specialDates || {} }];
}
function normalizeSchedule(schedule) {
  const profiles = normalizeProfiles(schedule);
  const active = profiles.find((p) => p.active) || profiles[0];
  if (!active) return null;
  return { days: active.days, blockedDates: active.blockedDates || [], specialDates: active.specialDates || {} };
}
function appointmentsNotCoveredBy(appointments, dentistId, profile, durationMin) {
  const today = todayStr();
  const asSchedule = { days: profile.days, blockedDates: profile.blockedDates || [], specialDates: profile.specialDates || {} };
  return appointments.filter((a) => {
    if (a.dentistId !== dentistId || !ACTIVE_STATUSES.includes(a.status) || a.date < today) return false;
    const slots = getSlotsForDate(asSchedule, a.date, a.durationMin || durationMin);
    return !slots.includes(a.time);
  }).sort((a, b) => (a.date + a.time).localeCompare(b.date + b.time));
}
function getSlotsForDate(rawSchedule, dateStr, durationMin, stepMin) {
  const step = stepMin || durationMin;
  const schedule = normalizeSchedule(rawSchedule);
  if (!schedule) return [];
  if ((schedule.blockedDates || []).includes(dateStr)) return [];
  const special = (schedule.specialDates || {})[dateStr];
  let dayCfg = null;
  if (special) {
    dayCfg = special;
  } else {
    const d = (schedule.days || {})[dowOf(dateStr)];
    if (d && d.enabled) dayCfg = d;
  }
  if (!dayCfg || !dayCfg.start || !dayCfg.end) return [];
  const startMin = timeToMin(dayCfg.start);
  const endMin = timeToMin(dayCfg.end);
  const breakStart = dayCfg.breakStart ? timeToMin(dayCfg.breakStart) : null;
  const breakEnd = dayCfg.breakEnd ? timeToMin(dayCfg.breakEnd) : null;
  const slots = [];
  for (let t = startMin; t + durationMin <= endMin; t += step) {
    if (breakStart !== null && breakEnd !== null && t < breakEnd && t + durationMin > breakStart) continue;
    slots.push(minToTime(t));
  }
  return slots;
}
function conflictsOnWeekday(appointments, dentistId, dow) {
  const today = todayStr();
  return appointments.filter((a) => a.dentistId === dentistId && ACTIVE_STATUSES.includes(a.status) && a.date >= today && dowOf(a.date) === dow)
    .sort((a, b) => (a.date + a.time).localeCompare(b.date + b.time));
}
function conflictsOnDate(appointments, dentistId, dateStr) {
  return appointments.filter((a) => a.dentistId === dentistId && ACTIVE_STATUSES.includes(a.status) && a.date === dateStr)
    .sort((a, b) => a.time.localeCompare(b.time));
}
function slotIsFree(appointments, dentistId, dateStr, timeStr, durationMin, excludeId) {
  const s = timeToMin(timeStr);
  const e = s + durationMin;
  return !appointments.some((a) => {
    if (a.id === excludeId) return false;
    if (a.dentistId !== dentistId || a.date !== dateStr) return false;
    if (!ACTIVE_STATUSES.includes(a.status)) return false;
    const as = timeToMin(a.time);
    const ae = as + (a.durationMin || durationMin);
    return s < ae && as < e;
  });
}

