/* ---------------- Error boundary (avoid silent blank screen) ---------------- */
class ErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { error: null }; }
  static getDerivedStateFromError(error) { return { error }; }
  componentDidCatch(error, info) { console.error("Vimax Dent error:", error, info); }
  render() {
    if (this.state.error) {
      return (
        <div className="vd-root" style={{ padding: 24 }}>
          <GlobalStyle />
          <div className="vd-card" style={{ padding: 20, maxWidth: 460, margin: "40px auto", borderColor: "var(--rose)" }}>
            <div style={{ fontWeight: 700, marginBottom: 8, color: "var(--rose)" }}>Ha ocurrido un problema al mostrar esta pantalla.</div>
            <div style={{ fontSize: 12.5, color: "var(--muted)", marginBottom: 14, wordBreak: "break-word" }}>{String(this.state.error?.message || this.state.error)}</div>
            <button className="vd-btn vd-btn-primary" onClick={() => this.setState({ error: null })}>Volver a intentar</button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

/* ============================================================
   APP ROOT
   ============================================================ */
function AppInner() {
  const [ready, setReady] = useState(false);
  const [toast, setToast] = useState(null);
  const notify = useCallback((msg, type = "ok") => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3200);
  }, []);

  // Data
  const [dentists, setDentists] = useState(SEED_DENTISTS);
  const [types, setTypes] = useState(SEED_TYPES);
  const [patients, setPatients] = useState([]);
  const [appointments, setAppointments] = useState([]);
  const [schedules, setSchedules] = useState(SEED_SCHEDULES);
  const [config, setConfig] = useState(SEED_CONFIG);
  const [notifications, setNotifications] = useState([]);
  const [users, setUsers] = useState(SEED_USERS);
  const [audit, setAudit] = useState([]);

  useEffect(() => {
    (async () => {
      const [d, t, p, a, s, c, n, u, au] = await Promise.all([
        loadKey(K.dentists, SEED_DENTISTS),
        loadKey(K.types, SEED_TYPES),
        loadKey(K.patients, []),
        loadKey(K.appointments, []),
        loadKey(K.schedules, SEED_SCHEDULES),
        loadKey(K.config, SEED_CONFIG),
        loadKey(K.notifications, []),
        loadKey(K.users, SEED_USERS),
        loadKey(K.audit, []),
      ]);
      setDentists(d); setTypes(t); setPatients(p); setAppointments(a);
      setSchedules(s); setConfig(c); setNotifications(n); setUsers(u); setAudit(au);
      setReady(true);
    })();
  }, []);

  const persist = {
    dentists: (v) => { setDentists(v); saveKey(K.dentists, v); },
    types: (v) => { setTypes(v); saveKey(K.types, v); },
    patients: (v) => { setPatients(v); saveKey(K.patients, v); },
    appointments: (v) => { setAppointments(v); saveKey(K.appointments, v); },
    schedules: (v) => { setSchedules(v); saveKey(K.schedules, v); },
    config: (v) => { setConfig(v); saveKey(K.config, v); },
    notifications: (v) => { setNotifications(v); saveKey(K.notifications, v); },
    users: (v) => { setUsers(v); saveKey(K.users, v); },
    audit: (v) => { setAudit(v); saveKey(K.audit, v); },
  };

  function pushAudit(action, detail, actor) {
    const entry = { id: uid("log"), action, detail, actor: actor || "sistema", at: new Date().toISOString() };
    persist.audit([entry, ...audit].slice(0, 500));
  }
  function pushNotification(text) {
    const entry = { id: uid("ntf"), text, read: false, at: new Date().toISOString() };
    persist.notifications([entry, ...notifications].slice(0, 200));
  }

  // Re-fetch appointments fresh right before a conflict-sensitive write (best-effort concurrency
  // guard given this is client-side shared storage — see architecture note at bottom of file).
  async function withFreshAppointments(fn) {
    const fresh = await loadKey(K.appointments, appointments);
    return fn(fresh);
  }

  function findOrCreatePatient(list, name, phone) {
    let existing = list.find((p) => p.phone && p.phone === phone);
    if (!existing) {
      // Paciente importado (ej. desde Word) sin teléfono guardado: si el
      // nombre coincide, es la misma persona que ya vino antes — no crear
      // un paciente nuevo, y aprovechamos para guardarle el teléfono.
      existing = list.find((p) => !p.phone && p.name.trim().toLowerCase() === name.trim().toLowerCase());
    }
    if (existing) {
      if (!existing.phone && phone) {
        const updated = { ...existing, phone };
        return { patient: updated, list: list.map((p) => p.id === existing.id ? updated : p) };
      }
      return { patient: existing, list };
    }
    const np = { id: uid("pat"), name, phone, createdAt: new Date().toISOString() };
    return { patient: np, list: [...list, np] };
  }

  /* -------- Session -------- */
  const [session, setSession] = useState(null); // {role, dentistId?, name}
  const [publicOverride, setPublicOverride] = useState(false); // ver el sitio público sin cerrar sesión

  /* -------- Top-level routing -------- */
  const [mode, setMode] = useState("public"); // public | staffLogin

  if (!ready) {
    return (
      <div className="vd-root vd-fade-in" style={{ minHeight: 500, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <GlobalStyle />
        <div style={{ textAlign: "center", color: "var(--muted)" }}>
          <Stethoscope size={28} style={{ marginBottom: 8 }} />
          <div>Cargando Vimax Dent…</div>
        </div>
      </div>
    );
  }

  const ctx = {
    dentists, types, patients, appointments, schedules, config, notifications, users, audit,
    persist, notify, pushAudit, pushNotification, withFreshAppointments, findOrCreatePatient,
  };

  return (
    <div className="vd-root">
      <GlobalStyle />
      {session?.role === "admin" && !publicOverride && <AdminPanel ctx={ctx} session={session} onLogout={() => { setSession(null); setPublicOverride(false); }} onGoHome={() => setPublicOverride(true)} />}
      {session?.role === "dentist" && !publicOverride && <DentistPanel ctx={ctx} session={session} onLogout={() => { setSession(null); setPublicOverride(false); }} onGoHome={() => setPublicOverride(true)} />}
      {!session && mode === "staffLogin" && <StaffLogin ctx={ctx} onBack={() => setMode("public")} onLogin={setSession} />}
      {(session && publicOverride) && <PublicSite ctx={ctx} onStaffClick={() => setMode("staffLogin")} staffSession={session} onBackToPanel={() => setPublicOverride(false)} />}
      {!session && mode === "public" && <PublicSite ctx={ctx} onStaffClick={() => setMode("staffLogin")} />}
      <Toast toast={toast} />
    </div>
  );
}

