/* -------- Booking wizard -------- */
function BookingWizard({ ctx, initialDentistId }) {
  const { dentists, types, schedules, config, appointments, patients, persist, notify, pushAudit, pushNotification, withFreshAppointments, findOrCreatePatient } = ctx;
  const [step, setStep] = useState(initialDentistId ? 2 : 1);
  const [dentistId, setDentistId] = useState(initialDentistId || "");
  const [date, setDate] = useState("");
  const [time, setTime] = useState("");
  const [typeId, setTypeId] = useState("");
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [reason, setReason] = useState("");
  const [extra, setExtra] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult] = useState(null);
  const [priorityMode, setPriorityMode] = useState(false);
  const [priorityProof, setPriorityProof] = useState(null);
  const [priorityUploading, setPriorityUploading] = useState(false);

  const activeDentists = dentists.filter((d) => d.active);
  const activeTypes = types.filter((t) => t.active);
  const schedule = schedules[dentistId];
  const duration = config.appointmentDurationMin || 30;
  const slotInterval = config.slotIntervalMin || duration;

  const minDate = todayStr();
  const maxDate = addDays(todayStr(), 60);
  const slots = date && schedule ? getSlotsForDate(schedule, date, duration, slotInterval).filter((t) => slotIsFree(appointments, dentistId, date, t, duration)) : [];

  function reset() {
    setStep(1); setDentistId(""); setDate(""); setTime(""); setTypeId(""); setName(""); setPhone(""); setReason(""); setExtra(""); setResult(null);
    setPriorityMode(false); setPriorityProof(null);
  }

  async function submit() {
    setSubmitting(true);
    try {
      await withFreshAppointments(async (fresh) => {
        if (!priorityMode && !slotIsFree(fresh, dentistId, date, time, duration)) {
          notify("Este horario acaba de ser reservado. Selecciona otro horario disponible.", "error");
          setStep(3);
          setTime("");
          setSubmitting(false);
          return;
        }
        const { patient, list: newPatients } = findOrCreatePatient(patients, name.trim(), phone.trim());
        const code = genCode(fresh.map((a) => a.code));
        const appt = {
          id: uid("apt"),
          code,
          dentistId,
          patientId: patient.id,
          patientName: name.trim(),
          patientPhone: phone.trim(),
          date, time, durationMin: duration,
          typeId, reason: reason.trim(), extra: extra.trim(),
          status: "pendiente",
          paidAmount: 0,
          notes: "", treatment: "",
          priority: priorityMode,
          priorityProof: priorityMode ? priorityProof : null,
          priorityApproved: false,
          createdAt: new Date().toISOString(),
          history: [{ at: new Date().toISOString(), event: priorityMode ? "Solicitud PRIORITARIA creada por el paciente (Bs 19)" : "Solicitud creada por el paciente" }],
        };
        persist.patients(newPatients);
        persist.appointments([appt, ...fresh]);
        pushAudit(priorityMode ? "Cita prioritaria solicitada" : "Cita solicitada", `${code} — ${name.trim()}`, "paciente");
        pushNotification(priorityMode ? `${name.trim()} solicitó una cita PRIORITARIA (${code}) — revisa el comprobante de pago.` : `${name.trim()} solicitó una cita (${code}).`);
        try {
          localStorage.setItem("vd_last_code", code);
          localStorage.setItem("vd_last_phone", phone.trim());
        } catch (e) {}
        setResult(appt);
        setStep(6);
        setSubmitting(false);
      });
    } catch (e) {
      notify("Ha ocurrido un problema al procesar tu solicitud. Inténtalo nuevamente.", "error");
      setSubmitting(false);
    }
  }

  if (step === 6 && result) {
    const dentist = dentists.find((d) => d.id === result.dentistId);
    return (
      <div className="vd-card" style={{ padding: 28, textAlign: "center" }}>
        <CheckCircle2 size={40} color="var(--teal)" style={{ marginBottom: 10 }} />
        <h2 className="vd-serif" style={{ fontSize: 22, fontWeight: 600, marginBottom: 6, color: "var(--ink)" }}>Solicitud enviada</h2>
        <p style={{ fontSize: 13, color: "var(--muted)", marginBottom: 18 }}>Tu cita quedó en estado <b>pendiente</b> hasta que la clínica la confirme.</p>
        <div style={{ background: "var(--teal-tint)", borderRadius: 12, padding: 18, marginBottom: 16 }}>
          <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 4 }}>Código de tu cita</div>
          <div className="vd-serif" style={{ fontSize: 28, fontWeight: 700, color: "var(--teal-deep)", letterSpacing: 1 }}>{result.code}</div>
        </div>
        <div style={{ textAlign: "left", fontSize: 14, display: "grid", gap: 6, marginBottom: 20 }}>
          <div><b>Odontólogo:</b> {dentist?.name}</div>
          <div><b>Fecha:</b> {fmtDateHuman(result.date)}</div>
          <div><b>Hora:</b> {result.time}</div>
        </div>
        <p style={{ fontSize: 12.5, color: "var(--muted)", marginBottom: 16 }}>Guarda este código: podrás usarlo junto a tu número de celular en "Mi cita" para consultar o gestionar tu reserva.</p>
        <Btn variant="ghost" onClick={reset}>Agendar otra cita</Btn>
      </div>
    );
  }

  return (
    <div>
      <h1 className="vd-serif" style={{ fontSize: 24, fontWeight: 600, color: "var(--ink)", marginBottom: 4 }}>Agendar cita</h1>
      <div style={{ fontSize: 12.5, color: "var(--muted)", marginBottom: 18 }}>Paso {step} de 5</div>

      {step === 1 && (
        <div className="vd-card vd-fade-in" style={{ padding: 20 }}>
          <div className="vd-label" style={{ marginBottom: 12 }}>Elige un odontólogo</div>
          <div style={{ display: "grid", gap: 10 }}>
            {activeDentists.map((d) => (
              <div key={d.id} className="vd-card" style={{ padding: 14, display: "flex", alignItems: "center", gap: 10, cursor: "pointer", borderColor: dentistId === d.id ? "var(--teal)" : "var(--border)", borderWidth: dentistId === d.id ? 2 : 1 }} onClick={() => setDentistId(d.id)}>
                <User size={18} color="var(--teal)" />
                <span style={{ fontWeight: 600, fontSize: 14 }}>{d.name}</span>
                {dentistId === d.id && <Check size={16} color="var(--teal)" style={{ marginLeft: "auto" }} />}
              </div>
            ))}
            {activeDentists.length === 0 && <Empty text="No hay odontólogos disponibles por el momento." />}
          </div>
          <div style={{ marginTop: 18, display: "flex", justifyContent: "flex-end" }}>
            <Btn disabled={!dentistId} onClick={() => setStep(2)}>Continuar <ChevronRight size={16} /></Btn>
          </div>
        </div>
      )}

      {step === 2 && (
        <div className="vd-card vd-fade-in" style={{ padding: 20 }}>
          <Field label="Elige una fecha">
            <input type="date" className="vd-input" min={minDate} max={maxDate} value={date} onChange={(e) => { setDate(e.target.value); setTime(""); }} />
          </Field>
          {date && !schedule && (
            <div style={{ marginTop: 14, fontSize: 13, color: "var(--rose)", display: "flex", gap: 8, alignItems: "flex-start" }}>
              <AlertTriangle size={16} style={{ flexShrink: 0, marginTop: 2 }} />
              Este odontólogo aún no tiene horarios configurados. Elige otro odontólogo o vuelve más tarde.
            </div>
          )}
          <div style={{ marginTop: 18, display: "flex", justifyContent: "space-between" }}>
            <Btn variant="ghost" onClick={() => setStep(1)}><ChevronLeft size={16} /> Atrás</Btn>
            <Btn disabled={!date || !schedule} onClick={() => setStep(3)}>Continuar <ChevronRight size={16} /></Btn>
          </div>
        </div>
      )}

      {step === 3 && (
        <div className="vd-card vd-fade-in" style={{ padding: 20 }}>
          {!priorityMode && (
            <>
              <div className="vd-label" style={{ marginBottom: 12 }}>Horarios disponibles — {fmtDateHuman(date)}</div>
              {slots.length === 0 ? (
                <Empty icon={Clock} text="No hay horarios disponibles ese día. Prueba con otra fecha." />
              ) : (
                <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(76px,1fr))", gap: 8 }}>
                  {slots.map((t) => (
                    <div key={t} className={`vd-slot ${time === t ? "selected" : ""}`} onClick={() => setTime(t)}>{t}</div>
                  ))}
                </div>
              )}
              <div className="vd-card" style={{ padding: 14, marginTop: 18, background: "var(--teal-tint)", border: "none" }}>
                <div style={{ fontWeight: 700, fontSize: 13.5, marginBottom: 4, color: "var(--ink)" }}>⚡ ¿Ningún horario te sirve?</div>
                <div style={{ fontSize: 12.5, color: "var(--text)", marginBottom: 10, lineHeight: 1.5 }}>
                  Puedes <b>solicitar</b> un horario prioritario por <b>Bs 19</b>: eliges cualquier hora, incluso si ya está
                  ocupada o si el odontólogo no la tiene habilitada. Es una <b>solicitud</b> — la clínica debe aceptarla
                  antes de quedar confirmada.
                </div>
                <Btn variant="gold" style={{ fontSize: 13, padding: "9px 14px" }} onClick={() => { setPriorityMode(true); setTime(""); }}>
                  Solicitar horario prioritario
                </Btn>
              </div>
            </>
          )}

          {priorityMode && (
            <div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                <div className="vd-label" style={{ marginBottom: 0 }}>Solicitud de horario prioritario</div>
                <button onClick={() => { setPriorityMode(false); setTime(""); setPriorityProof(null); }} style={{ background: "none", border: "none", color: "var(--muted)", fontSize: 12.5, cursor: "pointer", textDecoration: "underline" }}>Cancelar</button>
              </div>
              <div style={{ fontSize: 12.5, color: "var(--rose)", background: "#F6E4E6", borderRadius: 10, padding: 12, marginBottom: 14, lineHeight: 1.5 }}>
                <AlertTriangle size={14} style={{ display: "inline", marginRight: 6, verticalAlign: -2 }} />
                Esta es una <b>solicitud</b>, no una cita confirmada. El horario que elijas puede estar ocupado o fuera del
                horario habitual del odontólogo — la clínica revisará tu pago y la aceptará o te contactará para ajustarla.
              </div>
              <Field label="Elige cualquier hora"><input type="time" className="vd-input" value={time} onChange={(e) => setTime(e.target.value)} /></Field>

              <div className="vd-card" style={{ padding: 16, marginTop: 14, textAlign: "center" }}>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 8 }}>Paga Bs 19 y sube tu comprobante</div>
                <img src={PRIORITY_QR_URI} alt="QR de pago" style={{ width: 160, margin: "0 auto 6px", borderRadius: 10 }} />
                <div style={{ marginBottom: 10 }}>
                  <a href={PRIORITY_QR_URI} download="vimax-dent-qr-pago.png" style={{ fontSize: 12, color: "var(--teal-deep)", fontWeight: 600, textDecoration: "underline" }}>Descargar QR</a>
                </div>
                <label className="vd-btn vd-btn-ghost" style={{ cursor: "pointer", display: "inline-flex" }}>
                  {priorityUploading ? "Subiendo…" : priorityProof ? "Cambiar comprobante" : "Subir comprobante de pago"}
                  <input type="file" accept="image/*" style={{ display: "none" }} onChange={async (e) => {
                    const file = e.target.files?.[0];
                    if (!file) return;
                    setPriorityUploading(true);
                    try {
                      const dataUri = await fileToCompressedDataUri(file);
                      setPriorityProof(dataUri);
                    } catch (err) { notify("No se pudo procesar la imagen. Intenta con otra foto.", "error"); }
                    setPriorityUploading(false);
                  }} />
                </label>
                {priorityProof && (
                  <div style={{ marginTop: 12 }}>
                    <img src={priorityProof} alt="Comprobante" style={{ maxWidth: 160, borderRadius: 10, border: "2px solid var(--teal)" }} />
                    <div style={{ fontSize: 12, color: "var(--teal-deep)", marginTop: 6, fontWeight: 600 }}><Check size={13} style={{ display: "inline", verticalAlign: -2 }} /> Comprobante listo</div>
                  </div>
                )}
              </div>
            </div>
          )}

          <div style={{ marginTop: 18, display: "flex", justifyContent: "space-between" }}>
            <Btn variant="ghost" onClick={() => setStep(2)}><ChevronLeft size={16} /> Atrás</Btn>
            <Btn disabled={priorityMode ? (!time || !priorityProof) : !time} onClick={() => setStep(4)}>Continuar <ChevronRight size={16} /></Btn>
          </div>
        </div>
      )}

      {step === 4 && (
        <div className="vd-card vd-fade-in" style={{ padding: 20 }}>
          <div className="vd-label" style={{ marginBottom: 12 }}>Tipo de consulta</div>
          <div style={{ display: "grid", gap: 8 }}>
            {activeTypes.map((t) => (
              <div key={t.id} className="vd-card" style={{ padding: 12, cursor: "pointer", borderColor: typeId === t.id ? "var(--teal)" : "var(--border)", borderWidth: typeId === t.id ? 2 : 1, display: "flex", justifyContent: "space-between", alignItems: "center" }} onClick={() => setTypeId(t.id)}>
                <span style={{ fontSize: 14, fontWeight: 600 }}>{t.name}</span>
                {typeId === t.id && <Check size={16} color="var(--teal)" />}
              </div>
            ))}
          </div>
          <div style={{ marginTop: 18, display: "flex", justifyContent: "space-between" }}>
            <Btn variant="ghost" onClick={() => setStep(3)}><ChevronLeft size={16} /> Atrás</Btn>
            <Btn disabled={!typeId} onClick={() => setStep(5)}>Continuar <ChevronRight size={16} /></Btn>
          </div>
        </div>
      )}

      {step === 5 && (
        <div className="vd-card vd-fade-in" style={{ padding: 20 }}>
          <div style={{ display: "grid", gap: 12 }}>
            <Field label="Nombre completo"><input className="vd-input" value={name} onChange={(e) => setName(e.target.value)} placeholder="Ej. Ana Pérez" /></Field>
            <Field label="Número de celular / WhatsApp"><input className="vd-input" value={phone} onChange={(e) => setPhone(e.target.value.replace(/[^\d]/g, ""))} placeholder="Ej. 70012345" /></Field>
            <Field label="Motivo de consulta"><textarea className="vd-textarea" rows={2} value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Ej. Dolor en muela superior" /></Field>
            <Field label="Información adicional (opcional)"><textarea className="vd-textarea" rows={2} value={extra} onChange={(e) => setExtra(e.target.value)} /></Field>
          </div>

          <div className="vd-card" style={{ padding: 14, marginTop: 16, background: "var(--teal-tint)", border: "none" }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: "var(--ink)", marginBottom: 6 }}>Revisa tu solicitud</div>
            <div style={{ fontSize: 13, display: "grid", gap: 3 }}>
              <div>{dentists.find((d) => d.id === dentistId)?.name}</div>
              <div>{fmtDateHuman(date)} a las {time}</div>
              <div>{types.find((t) => t.id === typeId)?.name}</div>
              {priorityMode && <div style={{ fontWeight: 700, color: "var(--gold)" }}>⚡ Solicitud prioritaria — Bs 19 (pendiente de aprobación)</div>}
            </div>
          </div>

          <div style={{ marginTop: 18, display: "flex", justifyContent: "space-between" }}>
            <Btn variant="ghost" onClick={() => setStep(4)}><ChevronLeft size={16} /> Atrás</Btn>
            <Btn disabled={!name.trim() || phone.trim().length < 6 || submitting} onClick={submit}>
              {submitting ? "Enviando…" : "Solicitar cita"}
            </Btn>
          </div>
        </div>
      )}
    </div>
  );
}

/* -------- Mi cita -------- */
function MyAppointment({ ctx }) {
  const { appointments, dentists, config, persist, notify, pushAudit, pushNotification, schedules, withFreshAppointments } = ctx;
  const [code, setCode] = useState("");
  const [phone, setPhone] = useState("");
  const [found, setFound] = useState(null);
  const [searched, setSearched] = useState(false);
  const [rescheduling, setRescheduling] = useState(false);
  const [newDate, setNewDate] = useState("");
  const [newTime, setNewTime] = useState("");

  useEffect(() => {
    try {
      const c = localStorage.getItem("vd_last_code");
      const p = localStorage.getItem("vd_last_phone");
      if (c) setCode(c);
      if (p) setPhone(p);
    } catch (e) {}
  }, []);

  function search() {
    const norm = code.trim().toUpperCase();
    const a = appointments.find((x) => x.code.toUpperCase() === norm && x.patientPhone === phone.trim());
    setFound(a || null);
    setSearched(true);
    setRescheduling(false);
  }

  const dentist = found ? dentists.find((d) => d.id === found.dentistId) : null;
  const hUntil = found ? hoursUntil(found.date, found.time) : 0;
  const canManage = found && ACTIVE_STATUSES.includes(found.status);
  const withinWindow = hUntil >= (config.cancelWindowHours || 24);

  async function cancel() {
    await withFreshAppointments(async (fresh) => {
      const updated = fresh.map((a) => a.id === found.id ? { ...a, status: "cancelada", history: [...(a.history || []), { at: new Date().toISOString(), event: "Cancelada por el paciente" }] } : a);
      persist.appointments(updated);
      pushAudit("Cita cancelada", found.code, "paciente");
      pushNotification(`El paciente canceló la cita ${found.code}.`);
      setFound(updated.find((a) => a.id === found.id));
      notify("Tu cita fue cancelada.");
    });
  }

  const schedule = found ? schedules[found.dentistId] : null;
  const duration = found?.durationMin || config.appointmentDurationMin || 30;
  const slotInterval = config.slotIntervalMin || duration;
  const slots = newDate && schedule ? getSlotsForDate(schedule, newDate, duration, slotInterval).filter((t) => slotIsFree(appointments, found.dentistId, newDate, t, duration, found.id)) : [];

  async function confirmReschedule() {
    await withFreshAppointments(async (fresh) => {
      if (!slotIsFree(fresh, found.dentistId, newDate, newTime, duration, found.id)) {
        notify("Este horario acaba de ser reservado. Selecciona otro horario disponible.", "error");
        return;
      }
      const updated = fresh.map((a) => a.id === found.id ? {
        ...a, date: newDate, time: newTime, status: "reprogramada",
        history: [...(a.history || []), { at: new Date().toISOString(), event: `Reprogramada por el paciente: ${a.date} ${a.time} → ${newDate} ${newTime}` }],
      } : a);
      persist.appointments(updated);
      pushAudit("Cita reprogramada", found.code, "paciente");
      pushNotification(`El paciente reprogramó la cita ${found.code}.`);
      setFound(updated.find((a) => a.id === found.id));
      setRescheduling(false);
      notify("Tu cita fue reprogramada.");
    });
  }

  return (
    <div>
      <h1 className="vd-serif" style={{ fontSize: 24, fontWeight: 600, color: "var(--ink)", marginBottom: 14 }}>Mi cita</h1>
      <div className="vd-card" style={{ padding: 20 }}>
        <div style={{ display: "grid", gap: 12 }}>
          <Field label="Código de cita"><input className="vd-input" value={code} onChange={(e) => setCode(e.target.value)} placeholder="VD-XXXXX" /></Field>
          <Field label="Número de celular usado al reservar"><input className="vd-input" value={phone} onChange={(e) => setPhone(e.target.value.replace(/[^\d]/g, ""))} /></Field>
        </div>
        <Btn style={{ marginTop: 14 }} onClick={search} disabled={!code.trim() || !phone.trim()}><Search size={16} /> Buscar cita</Btn>

        {searched && !found && <div style={{ marginTop: 16, fontSize: 13.5, color: "var(--rose)" }}>No encontramos una cita con esos datos. Verifica el código y el número de celular.</div>}

        {found && (
          <div className="vd-fade-in" style={{ marginTop: 18, borderTop: "1px solid var(--border)", paddingTop: 16 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
              <span className="vd-serif" style={{ fontSize: 18, fontWeight: 700 }}>{found.code}</span>
              <div style={{ display: "flex", gap: 6 }}>
                {found.priorityApproved && <VimaxPlusBadge />}
                <Badge status={found.status} />
              </div>
            </div>
            <div style={{ fontSize: 14, display: "grid", gap: 4, marginBottom: 14 }}>
              <div><b>Odontólogo:</b> {dentist?.name}</div>
              <div><b>Fecha:</b> {fmtDateHuman(found.date)}</div>
              <div><b>Hora:</b> {found.time}</div>
            </div>

            {canManage && !rescheduling && (
              withinWindow ? (
                <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
                  <Btn variant="danger" onClick={cancel}>Cancelar cita</Btn>
                  <Btn variant="ghost" onClick={() => setRescheduling(true)}>Reprogramar</Btn>
                </div>
              ) : (
                <div>
                  <div style={{ fontSize: 13, color: "var(--rose)", marginBottom: 10, display: "flex", gap: 8 }}>
                    <AlertTriangle size={16} style={{ flexShrink: 0 }} />
                    Faltan menos de {config.cancelWindowHours} horas para tu cita, así que no puedes cancelarla ni reprogramarla desde aquí. Contacta directamente a tu odontólogo.
                  </div>
                  <a href={waLink(dentist?.phone, `Hola, soy ${found.patientName}, tengo la cita ${found.code} y necesito contactarte.`)} target="_blank" rel="noreferrer">
                    <Btn variant="primary"><MessageCircle size={16} /> Contactar al odontólogo</Btn>
                  </a>
                </div>
              )
            )}

            {rescheduling && (
              <div style={{ marginTop: 10 }}>
                <Field label="Nueva fecha"><input type="date" className="vd-input" min={todayStr()} value={newDate} onChange={(e) => { setNewDate(e.target.value); setNewTime(""); }} /></Field>
                {newDate && (
                  <div style={{ marginTop: 10 }}>
                    {slots.length === 0 ? <div style={{ fontSize: 13, color: "var(--muted)" }}>Sin horarios disponibles ese día.</div> : (
                      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(70px,1fr))", gap: 8 }}>
                        {slots.map((t) => <div key={t} className={`vd-slot ${newTime === t ? "selected" : ""}`} onClick={() => setNewTime(t)}>{t}</div>)}
                      </div>
                    )}
                  </div>
                )}
                <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
                  <Btn variant="ghost" onClick={() => setRescheduling(false)}>Cancelar</Btn>
                  <Btn disabled={!newTime} onClick={confirmReschedule}>Confirmar cambio</Btn>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}


/* ============================================================
   STAFF LOGIN
   ============================================================ */
function StaffLogin({ ctx, onBack, onLogin }) {
  const { users, config } = ctx;
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  function submit(e) {
    e.preventDefault();
    const normUser = username.trim().toLowerCase();
    const normPass = password.trim();
    const u = users.find((x) => x.username.toLowerCase() === normUser && x.password === normPass);
    if (!u) { setError("Usuario o contraseña incorrectos."); return; }
    onLogin(u.role === "admin" ? { role: "admin", name: u.name } : { role: "dentist", dentistId: u.dentistId, name: u.name });
  }

  return (
    <div style={{ minHeight: 480, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
      <div className="vd-card vd-fade-in" style={{ padding: 28, maxWidth: 360, width: "100%" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 18 }}>
          <button onClick={onBack} style={{ background: "none", border: "none", cursor: "pointer", color: "var(--muted)" }}><ArrowLeft size={18} /></button>
          <span className="vd-serif" style={{ fontSize: 18, fontWeight: 600, color: "var(--ink)" }}>Acceso staff — {config.clinicName}</span>
        </div>
        <form onSubmit={submit} style={{ display: "grid", gap: 12 }}>
          <Field label="Usuario"><input className="vd-input" value={username} onChange={(e) => setUsername(e.target.value)} autoCapitalize="none" autoCorrect="off" spellCheck="false" autoComplete="username" /></Field>
          <Field label="Contraseña"><input type="password" className="vd-input" value={password} onChange={(e) => setPassword(e.target.value)} autoCapitalize="none" autoCorrect="off" spellCheck="false" autoComplete="current-password" /></Field>
          {error && <div style={{ fontSize: 13, color: "var(--rose)" }}>{error}</div>}
          <Btn type="button" onClick={submit}>Ingresar</Btn>
        </form>
      </div>
    </div>
  );
}

