function StatCard({ label, value, icon: Icon }) {
  return (
    <div className="vd-card" style={{ padding: 16 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
        <div>
          <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 6 }}>{label}</div>
          <div className="vd-serif" style={{ fontSize: 24, fontWeight: 700, color: "var(--ink)" }}>{value}</div>
        </div>
        <Icon size={18} color="var(--teal)" />
      </div>
    </div>
  );
}

function AdminDashboard({ ctx }) {
  const { appointments, patients, dentists } = ctx;
  const today = todayStr();
  const todays = appointments.filter((a) => a.date === today && ACTIVE_STATUSES.includes(a.status));
  const pending = appointments.filter((a) => a.status === "pendiente");
  const upcoming = appointments.filter((a) => a.date >= today && ACTIVE_STATUSES.includes(a.status)).sort((a, b) => (a.date + a.time).localeCompare(b.date + b.time)).slice(0, 6);
  const cancelled = appointments.filter((a) => a.status === "cancelada").length;
  const rescheduled = appointments.filter((a) => a.history && a.history.some((h) => h.event.includes("eprogramad"))).length;
  const completed = appointments.filter((a) => a.status === "completada").length;
  const totalMoney = appointments.reduce((s, a) => s + (Number(a.paidAmount) || 0), 0);
  const byDentist = dentists.map((d) => ({ name: d.name, count: appointments.filter((a) => a.dentistId === d.id && ACTIVE_STATUSES.includes(a.status)).length }));

  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(160px,1fr))", gap: 12, marginBottom: 20 }}>
        <StatCard label="Citas de hoy" value={todays.length} icon={CalendarDays} />
        <StatCard label="Pendientes de aprobación" value={pending.length} icon={Clock} />
        <StatCard label="Total pacientes" value={patients.length} icon={Users} />
        <StatCard label="Completadas" value={completed} icon={CheckCircle2} />
        <StatCard label="Canceladas" value={cancelled} icon={XCircle} />
        <StatCard label="Reprogramadas" value={rescheduled} icon={RotateCcw} />
        <StatCard label="Ingresos registrados" value={`Bs ${totalMoney}`} icon={DollarSign} />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1.2fr 1fr", gap: 14 }} className="vd-dash-grid">
        <style>{`@media(max-width:760px){ .vd-dash-grid{ grid-template-columns: 1fr !important; } }`}</style>
        <div className="vd-card" style={{ padding: 16 }}>
          <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 10 }}>Próximas citas</div>
          {upcoming.length === 0 ? <Empty text="No hay citas próximas." /> : (
            <div style={{ display: "grid", gap: 8 }}>
              {upcoming.map((a) => (
                <div key={a.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "8px 0", borderBottom: "1px solid var(--border)" }}>
                  <div>
                    <div style={{ fontWeight: 600, fontSize: 13.5 }}>{a.patientName}</div>
                    <div style={{ fontSize: 12, color: "var(--muted)" }}>{fmtDateShort(a.date)} · {a.time} · {dentists.find((d) => d.id === a.dentistId)?.name}</div>
                  </div>
                  <Badge status={a.status} />
                </div>
              ))}
            </div>
          )}
        </div>
        <div className="vd-card" style={{ padding: 16 }}>
          <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 10 }}>Citas activas por odontólogo</div>
          <div style={{ display: "grid", gap: 10 }}>
            {byDentist.map((d) => (
              <div key={d.name}>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 4 }}><span>{d.name}</span><b>{d.count}</b></div>
                <div style={{ background: "var(--teal-tint)", borderRadius: 6, height: 8 }}>
                  <div style={{ width: `${Math.min(100, d.count * 10)}%`, background: "var(--teal)", height: 8, borderRadius: 6 }} />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

function AdminAppointments({ ctx }) {
  return <AppointmentsManager ctx={ctx} scopeDentistId={null} title="Todas las citas" allowManual allowFilters />;
}

function AppointmentsManager({ ctx, scopeDentistId, title, allowManual, allowFilters, actorLabel = "admin" }) {
  const { appointments, dentists, patients, types, config, schedules, persist, notify, pushAudit, pushNotification, withFreshAppointments, findOrCreatePatient } = ctx;
  const [filterDentist, setFilterDentist] = useState(scopeDentistId || "all");
  const [filterStatus, setFilterStatus] = useState("all");
  const [filterView, setFilterView] = useState("all"); // day/week/month/all
  const [anchorDate, setAnchorDate] = useState(todayStr());
  const [manualOpen, setManualOpen] = useState(false);
  const [detail, setDetail] = useState(null);
  const [rescheduleFor, setRescheduleFor] = useState(null);

  const rangeFilter = (a) => {
    if (filterView === "all") return true;
    if (filterView === "day") return a.date === anchorDate;
    if (filterView === "week") {
      const start = addDays(anchorDate, -dowOf(anchorDate));
      const end = addDays(start, 6);
      return a.date >= start && a.date <= end;
    }
    if (filterView === "month") return a.date.slice(0, 7) === anchorDate.slice(0, 7);
    return true;
  };

  const list = appointments
    .filter((a) => (scopeDentistId ? a.dentistId === scopeDentistId : true))
    .filter((a) => (filterDentist === "all" ? true : a.dentistId === filterDentist))
    .filter((a) => (filterStatus === "all" ? true : a.status === filterStatus))
    .filter(rangeFilter)
    .sort((a, b) => (a.date + a.time).localeCompare(b.date + b.time));

  async function changeStatus(appt, status, extraHistory) {
    await withFreshAppointments(async (fresh) => {
      const updated = fresh.map((a) => a.id === appt.id ? { ...a, status, history: [...(a.history || []), { at: new Date().toISOString(), event: extraHistory || `Estado cambiado a ${STATUS_LABELS[status]}` }] } : a);
      persist.appointments(updated);
      pushAudit(`Cita ${status}`, appt.code, actorLabel);
      pushNotification(`La cita ${appt.code} fue marcada como ${STATUS_LABELS[status].toLowerCase()}.`);
      notify(`Cita ${STATUS_LABELS[status].toLowerCase()}.`);
      setDetail(null);
    });
  }

  return (
    <div>
      {allowFilters && (
        <div className="vd-card" style={{ padding: 14, marginBottom: 14, display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
          <select className="vd-select" style={{ width: "auto" }} value={filterView} onChange={(e) => setFilterView(e.target.value)}>
            <option value="day">Día</option><option value="week">Semana</option><option value="month">Mes</option><option value="all">Todas</option>
          </select>
          {filterView !== "all" && <input type="date" className="vd-input" style={{ width: "auto" }} value={anchorDate} onChange={(e) => setAnchorDate(e.target.value)} />}
          {!scopeDentistId && (
            <select className="vd-select" style={{ width: "auto" }} value={filterDentist} onChange={(e) => setFilterDentist(e.target.value)}>
              <option value="all">Todos los odontólogos</option>
              {dentists.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
            </select>
          )}
          <select className="vd-select" style={{ width: "auto" }} value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
            <option value="all">Todos los estados</option>
            {Object.keys(STATUS_LABELS).map((s) => <option key={s} value={s}>{STATUS_LABELS[s]}</option>)}
          </select>
          {allowManual && <Btn style={{ marginLeft: "auto" }} onClick={() => setManualOpen(true)}><Plus size={16} /> Cita manual</Btn>}
        </div>
      )}
      {!allowFilters && allowManual && <Btn onClick={() => setManualOpen(true)} style={{ marginBottom: 14 }}><Plus size={16} /> Cita manual</Btn>}

      <div style={{ display: "grid", gap: 8 }}>
        {list.length === 0 && <Empty text="No hay citas para este filtro." />}
        {list.map((a) => (
          <div key={a.id} className="vd-card" style={{ padding: 14, cursor: "pointer" }} onClick={() => setDetail(a)}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <div style={{ fontWeight: 700, fontSize: 14 }}>{a.patientName} <span style={{ color: "var(--muted)", fontWeight: 500 }}>· {a.code}</span></div>
                <div style={{ fontSize: 12.5, color: "var(--muted)" }}>
                  {fmtDateShort(a.date)} · {a.time} · {dentists.find((d) => d.id === a.dentistId)?.name} · {types.find((t) => t.id === a.typeId)?.name || "—"}
                </div>
              </div>
              <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
                {a.priorityApproved && <VimaxPlusBadge />}
                {a.priority && !a.priorityApproved && <span className="vd-badge" style={{ background: "#FDEAD6", color: "var(--gold)" }}>⚡ Prioritaria</span>}
                <Badge status={a.status} />
              </div>
            </div>
          </div>
        ))}
      </div>

      <Modal open={!!detail} onClose={() => setDetail(null)} title={detail ? `Cita ${detail.code}` : ""} wide>
        {detail && (
          <AppointmentDetail
            appt={detail}
            ctx={ctx}
            onClose={() => setDetail(null)}
            onChangeStatus={changeStatus}
            onReschedule={() => { setRescheduleFor(detail); setDetail(null); }}
            actorLabel={actorLabel}
          />
        )}
      </Modal>

      <Modal open={!!rescheduleFor} onClose={() => setRescheduleFor(null)} title="Reprogramar cita">
        {rescheduleFor && (
          <RescheduleForm
            ctx={ctx}
            appt={rescheduleFor}
            actorLabel={actorLabel}
            onDone={() => setRescheduleFor(null)}
          />
        )}
      </Modal>

      <Modal open={manualOpen} onClose={() => setManualOpen(false)} title="Nueva cita manual" wide>
        <ManualAppointmentForm ctx={ctx} scopeDentistId={scopeDentistId} actorLabel={actorLabel} onDone={() => setManualOpen(false)} />
      </Modal>
    </div>
  );
}

function PriorityProofsPanel({ ctx, scopeDentistId, actorLabel }) {
  const { appointments, dentists, config, persist, withFreshAppointments, notify, pushAudit, pushNotification } = ctx;
  const [openProof, setOpenProof] = useState(null);

  const list = appointments
    .filter((a) => a.priority && (scopeDentistId ? a.dentistId === scopeDentistId : true))
    .sort((a, b) => {
      const rank = (a) => (a.status === "pendiente" && !a.priorityApproved ? 0 : 1);
      const r = rank(a) - rank(b);
      return r !== 0 ? r : (b.date + b.time).localeCompare(a.date + a.time);
    });

  async function approve(appt) {
    await withFreshAppointments(async (fresh) => {
      const updated = fresh.map((a) => a.id === appt.id ? { ...a, status: "confirmada", priorityApproved: true, history: [...(a.history || []), { at: new Date().toISOString(), event: "Pago prioritario aprobado — Vimax Plus activado" }] } : a);
      persist.appointments(updated);
      pushAudit("Prioridad aprobada (Vimax Plus)", appt.code, actorLabel);
      pushNotification(`La cita ${appt.code} fue confirmada como Vimax Plus.`);
      notify("Cita confirmada con insignia Vimax Plus 🔥.");
    });
  }
  async function reject(appt) {
    await withFreshAppointments(async (fresh) => {
      const updated = fresh.map((a) => a.id === appt.id ? { ...a, status: "rechazada", history: [...(a.history || []), { at: new Date().toISOString(), event: "Solicitud prioritaria rechazada" }] } : a);
      persist.appointments(updated);
      pushAudit("Prioridad rechazada", appt.code, actorLabel);
      pushNotification(`La solicitud prioritaria ${appt.code} fue rechazada.`);
      notify("Solicitud rechazada.");
    });
  }

  return (
    <div>
      <div style={{ fontSize: 12.5, color: "var(--muted)", marginBottom: 14 }}>Solicitudes de horario prioritario (Bs 19) — revisa el comprobante antes de aprobar.</div>
      <div style={{ display: "grid", gap: 10 }}>
        {list.length === 0 && <Empty icon={DollarSign} text="No hay solicitudes prioritarias todavía." />}
        {list.map((a) => {
          const dentist = dentists.find((d) => d.id === a.dentistId);
          const pending = a.status === "pendiente" && !a.priorityApproved;
          return (
            <div key={a.id} className="vd-card" style={{ padding: 14 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10 }}>
                <div>
                  <div style={{ fontWeight: 700, fontSize: 14 }}>{a.patientName} <span style={{ color: "var(--muted)", fontWeight: 500 }}>· {a.code}</span></div>
                  <div style={{ fontSize: 12.5, color: "var(--muted)" }}>{fmtDateShort(a.date)} · {a.time} · {!scopeDentistId ? dentist?.name + " · " : ""}{a.patientPhone}</div>
                </div>
                <div style={{ display: "flex", gap: 6, flexShrink: 0 }}>
                  {a.priorityApproved && <VimaxPlusBadge />}
                  <Badge status={a.status} />
                </div>
              </div>

              <div style={{ display: "flex", gap: 12, alignItems: "flex-start", marginTop: 12, flexWrap: "wrap" }}>
                {a.priorityProof ? (
                  <img src={a.priorityProof} alt="Comprobante" style={{ width: 84, height: 84, objectFit: "cover", borderRadius: 8, border: "1px solid var(--border)", cursor: "pointer" }} onClick={() => setOpenProof(a.priorityProof)} />
                ) : (
                  <div style={{ fontSize: 12.5, color: "var(--rose)" }}>⚠️ Sin comprobante subido</div>
                )}
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap", flex: 1 }}>
                  <a href={waLink(a.patientPhone, `Hola ${a.patientName}, soy de Vimax Dent, te contacto por tu cita ${a.code}.`)} target="_blank" rel="noreferrer">
                    <Btn variant="ghost" style={{ padding: "8px 12px", fontSize: 12.5 }}><MessageCircle size={14} /> Contactar</Btn>
                  </a>
                  {pending && (
                    <>
                      <Btn variant="gold" style={{ padding: "8px 12px", fontSize: 12.5 }} onClick={() => approve(a)}>🔥 Aprobar</Btn>
                      <Btn variant="danger" style={{ padding: "8px 12px", fontSize: 12.5 }} onClick={() => reject(a)}><X size={14} /> Rechazar</Btn>
                    </>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
      <Modal open={!!openProof} onClose={() => setOpenProof(null)} title="Comprobante de pago">
        {openProof && <img src={openProof} alt="Comprobante" style={{ width: "100%", borderRadius: 10 }} />}
      </Modal>
    </div>
  );
}

function AppointmentDetail({ appt, ctx, onClose, onChangeStatus, onReschedule, actorLabel }) {
  const { dentists, types, patients, persist, appointments, withFreshAppointments, notify, pushAudit, pushNotification } = ctx;
  const dentist = dentists.find((d) => d.id === appt.dentistId);
  const [notes, setNotes] = useState(appt.notes || "");
  const [treatment, setTreatment] = useState(appt.treatment || "");
  const [paid, setPaid] = useState(appt.paidAmount || 0);

  const conflicts = appt.priority
    ? appointments.filter((a) => a.id !== appt.id && a.dentistId === appt.dentistId && a.date === appt.date && a.time === appt.time && ACTIVE_STATUSES.includes(a.status))
    : [];

  async function approvePriority() {
    await withFreshAppointments(async (fresh) => {
      const updated = fresh.map((a) => a.id === appt.id ? { ...a, status: "confirmada", priorityApproved: true, history: [...(a.history || []), { at: new Date().toISOString(), event: "Pago prioritario aprobado — Vimax Plus activado" }] } : a);
      persist.appointments(updated);
      pushAudit("Prioridad aprobada (Vimax Plus)", appt.code, actorLabel);
      pushNotification(`La cita ${appt.code} fue confirmada como Vimax Plus.`);
      notify("Cita confirmada con insignia Vimax Plus 🔥.");
      onClose();
    });
  }

  async function saveAttention() {
    await withFreshAppointments(async (fresh) => {
      const updated = fresh.map((a) => a.id === appt.id ? { ...a, notes, treatment, paidAmount: Number(paid) || 0, status: a.status === "pendiente" ? a.status : "completada", history: [...(a.history || []), { at: new Date().toISOString(), event: "Atención registrada" }] } : a);
      persist.appointments(updated);
      pushAudit("Atención registrada", appt.code, actorLabel);
      notify("Atención guardada.");
      onClose();
    });
  }

  return (
    <div style={{ display: "grid", gap: 14 }}>
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <div style={{ fontSize: 14 }}>
          <div><b>Paciente:</b> {appt.patientName} ({appt.patientPhone})</div>
          <div><b>Odontólogo:</b> {dentist?.name}</div>
          <div><b>Fecha/hora:</b> {fmtDateHuman(appt.date)}, {appt.time}</div>
          <div><b>Tipo:</b> {types.find((t) => t.id === appt.typeId)?.name || "—"}</div>
          <div><b>Motivo:</b> {appt.reason || "—"}</div>
        </div>
        <div style={{ display: "grid", gap: 6, justifyItems: "end" }}>
          <Badge status={appt.status} />
          {appt.priorityApproved && <VimaxPlusBadge />}
        </div>
      </div>

      {appt.priority && (
        <div className="vd-card" style={{ padding: 14, background: "var(--teal-tint)", border: "none" }}>
          <div style={{ fontWeight: 700, fontSize: 13.5, marginBottom: 8 }}>⚡ Solicitud prioritaria — Bs 19</div>
          {conflicts.length > 0 && (
            <div style={{ fontSize: 12.5, color: "var(--rose)", marginBottom: 10, display: "flex", gap: 6 }}>
              <AlertTriangle size={14} style={{ flexShrink: 0, marginTop: 2 }} />
              <span>Este horario se cruza con {conflicts.length} cita(s) ya activa(s): {conflicts.map((c) => `${c.patientName} (${STATUS_LABELS[c.status]})`).join(", ")}. Revisa antes de aprobar.</span>
            </div>
          )}
          {appt.priorityProof ? (
            <div>
              <div style={{ fontSize: 12.5, color: "var(--muted)", marginBottom: 6 }}>Comprobante de pago:</div>
              <a href={appt.priorityProof} target="_blank" rel="noreferrer">
                <img src={appt.priorityProof} alt="Comprobante" style={{ maxWidth: 160, borderRadius: 8, border: "1px solid var(--border)" }} />
              </a>
            </div>
          ) : (
            <div style={{ fontSize: 12.5, color: "var(--rose)" }}>⚠️ El paciente no subió comprobante de pago.</div>
          )}
          {!appt.priorityApproved && (
            <Btn variant="gold" style={{ marginTop: 12 }} onClick={approvePriority}>🔥 Aprobar y activar Vimax Plus</Btn>
          )}
        </div>
      )}

      {appt.status === "pendiente" && (
        <div style={{ display: "flex", gap: 10 }}>
          <Btn onClick={() => onChangeStatus(appt, "confirmada")}><Check size={16} /> Aprobar</Btn>
          <Btn variant="danger" onClick={() => onChangeStatus(appt, "rechazada")}><X size={16} /> Rechazar</Btn>
        </div>
      )}
      {ACTIVE_STATUSES.includes(appt.status) && (
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
          <Btn variant="ghost" onClick={onReschedule}><RotateCcw size={16} /> Reprogramar</Btn>
          <Btn variant="danger" onClick={() => onChangeStatus(appt, "cancelada")}><X size={16} /> Cancelar</Btn>
          <Btn variant="ghost" onClick={() => onChangeStatus(appt, "no_asistio")}>Marcar no asistió</Btn>
        </div>
      )}

      <div style={{ borderTop: "1px solid var(--border)", paddingTop: 14 }}>
        <div style={{ fontWeight: 700, fontSize: 13.5, marginBottom: 8 }}>Registrar atención</div>
        <div style={{ display: "grid", gap: 10 }}>
          <Field label="Tratamiento realizado"><input className="vd-input" value={treatment} onChange={(e) => setTreatment(e.target.value)} /></Field>
          <Field label="Notas (opcional)"><textarea className="vd-textarea" rows={2} value={notes} onChange={(e) => setNotes(e.target.value)} /></Field>
          <Field label="Importe pagado (Bs)"><input type="number" className="vd-input" value={paid} onChange={(e) => setPaid(e.target.value)} /></Field>
          <Btn onClick={saveAttention}>Guardar atención</Btn>
        </div>
      </div>

      {appt.history?.length > 0 && (
        <div style={{ borderTop: "1px solid var(--border)", paddingTop: 12 }}>
          <div style={{ fontWeight: 700, fontSize: 12.5, marginBottom: 6, color: "var(--muted)" }}>Historial de cambios</div>
          <div style={{ display: "grid", gap: 4 }}>
            {appt.history.map((h, i) => (
              <div key={i} style={{ fontSize: 12, color: "var(--muted)" }}>{new Date(h.at).toLocaleString("es-BO")} — {h.event}</div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

function RescheduleForm({ ctx, appt, actorLabel, onDone }) {
  const { schedules, config, appointments, persist, notify, pushAudit, pushNotification, withFreshAppointments } = ctx;
  const [date, setDate] = useState(appt.date);
  const [time, setTime] = useState("");
  const schedule = schedules[appt.dentistId];
  const duration = appt.durationMin || config.appointmentDurationMin || 30;
  const slotInterval = config.slotIntervalMin || duration;
  const slots = date && schedule ? getSlotsForDate(schedule, date, duration, slotInterval).filter((t) => slotIsFree(appointments, appt.dentistId, date, t, duration, appt.id)) : [];

  async function confirm() {
    await withFreshAppointments(async (fresh) => {
      if (!slotIsFree(fresh, appt.dentistId, date, time, duration, appt.id)) {
        notify("Este horario acaba de ser reservado. Selecciona otro horario disponible.", "error");
        return;
      }
      const updated = fresh.map((a) => a.id === appt.id ? { ...a, date, time, status: "reprogramada", history: [...(a.history || []), { at: new Date().toISOString(), event: `Reprogramada (${actorLabel}): ${a.date} ${a.time} → ${date} ${time}` }] } : a);
      persist.appointments(updated);
      pushAudit("Cita reprogramada", appt.code, actorLabel);
      pushNotification(`La cita ${appt.code} fue reprogramada.`);
      notify("Cita reprogramada.");
      onDone();
    });
  }

  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Field label="Nueva fecha"><input type="date" className="vd-input" min={todayStr()} value={date} onChange={(e) => { setDate(e.target.value); setTime(""); }} /></Field>
      {slots.length === 0 ? <div style={{ fontSize: 13, color: "var(--muted)" }}>Sin horarios disponibles ese día.</div> : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(70px,1fr))", gap: 8 }}>
          {slots.map((t) => <div key={t} className={`vd-slot ${time === t ? "selected" : ""}`} onClick={() => setTime(t)}>{t}</div>)}
        </div>
      )}
      <Btn disabled={!time} onClick={confirm}>Confirmar reprogramación</Btn>
    </div>
  );
}

function ManualAppointmentForm({ ctx, scopeDentistId, actorLabel, onDone }) {
  const { dentists, types, schedules, config, appointments, patients, persist, notify, pushAudit, pushNotification, withFreshAppointments, findOrCreatePatient } = ctx;
  const [dentistId, setDentistId] = useState(scopeDentistId || "");
  const [date, setDate] = useState("");
  const [time, setTime] = useState("");
  const [typeId, setTypeId] = useState(types[0]?.id || "");
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [reason, setReason] = useState("");

  const schedule = schedules[dentistId];
  const duration = config.appointmentDurationMin || 30;
  const slotInterval = config.slotIntervalMin || duration;
  const slots = date && schedule ? getSlotsForDate(schedule, date, duration, slotInterval).filter((t) => slotIsFree(appointments, dentistId, date, t, duration)) : [];

  async function submit() {
    await withFreshAppointments(async (fresh) => {
      if (!slotIsFree(fresh, dentistId, date, time, duration)) {
        notify("Este horario acaba de ser reservado. Selecciona otro horario disponible.", "error");
        return;
      }
      const { patient, list: newPatients } = findOrCreatePatient(patients, name.trim(), phone.trim());
      const code = genCode(fresh.map((a) => a.code));
      const appt = {
        id: uid("apt"), code, dentistId, patientId: patient.id, patientName: name.trim(), patientPhone: phone.trim(),
        date, time, durationMin: duration, typeId, reason: reason.trim(), extra: "",
        status: "confirmada", paidAmount: 0, notes: "", treatment: "",
        createdAt: new Date().toISOString(),
        history: [{ at: new Date().toISOString(), event: `Creada manualmente por ${actorLabel}` }],
      };
      persist.patients(newPatients);
      persist.appointments([appt, ...fresh]);
      pushAudit("Cita manual creada", code, actorLabel);
      pushNotification(`Se creó una cita manual para ${name.trim()} (${code}).`);
      notify("Cita creada.");
      onDone();
    });
  }

  return (
    <div style={{ display: "grid", gap: 12 }}>
      {!scopeDentistId && (
        <Field label="Odontólogo">
          <select className="vd-select" value={dentistId} onChange={(e) => { setDentistId(e.target.value); setDate(""); setTime(""); }}>
            <option value="">Selecciona…</option>
            {dentists.filter((d) => d.active).map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
          </select>
        </Field>
      )}
      <Field label="Fecha"><input type="date" className="vd-input" value={date} onChange={(e) => { setDate(e.target.value); setTime(""); }} /></Field>
      {date && !schedule && <div style={{ fontSize: 13, color: "var(--rose)" }}>Este odontólogo no tiene horario configurado.</div>}
      {slots.length > 0 && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(70px,1fr))", gap: 8 }}>
          {slots.map((t) => <div key={t} className={`vd-slot ${time === t ? "selected" : ""}`} onClick={() => setTime(t)}>{t}</div>)}
        </div>
      )}
      <Field label="Tipo de consulta">
        <select className="vd-select" value={typeId} onChange={(e) => setTypeId(e.target.value)}>
          {types.filter((t) => t.active).map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
        </select>
      </Field>
      <Field label="Nombre del paciente"><input className="vd-input" value={name} onChange={(e) => setName(e.target.value)} /></Field>
      <Field label="Celular"><input className="vd-input" value={phone} onChange={(e) => setPhone(e.target.value.replace(/[^\d]/g, ""))} /></Field>
      <Field label="Motivo"><textarea className="vd-textarea" rows={2} value={reason} onChange={(e) => setReason(e.target.value)} /></Field>
      <Btn disabled={!dentistId || !date || !time || !name.trim() || phone.trim().length < 6} onClick={submit}>Crear cita</Btn>
    </div>
  );
}

function AdminPatients({ ctx }) {
  const { patients, appointments } = ctx;
  const [q, setQ] = useState("");
  const [openPatient, setOpenPatient] = useState(null);
  const filtered = patients.filter((p) => p.name.toLowerCase().includes(q.toLowerCase()) || p.phone.includes(q));

  return (
    <div>
      <div style={{ marginBottom: 14, position: "relative" }}>
        <Search size={16} style={{ position: "absolute", left: 12, top: 13, color: "var(--muted)" }} />
        <input className="vd-input" style={{ paddingLeft: 34 }} placeholder="Buscar por nombre o celular…" value={q} onChange={(e) => setQ(e.target.value)} />
      </div>
      <div style={{ display: "grid", gap: 8 }}>
        {filtered.length === 0 && <Empty icon={Users} text="No hay pacientes registrados todavía." />}
        {filtered.map((p) => {
          const count = appointments.filter((a) => a.patientId === p.id).length;
          return (
            <div key={p.id} className="vd-card" style={{ padding: 14, cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }} onClick={() => setOpenPatient(p)}>
              <div>
                <div style={{ fontWeight: 700, fontSize: 14 }}>{p.name}</div>
                <div style={{ fontSize: 12.5, color: "var(--muted)" }}>{p.phone}</div>
              </div>
              <div style={{ fontSize: 12, color: "var(--muted)" }}>{count} cita(s)</div>
            </div>
          );
        })}
      </div>
      <Modal open={!!openPatient} onClose={() => setOpenPatient(null)} title={openPatient?.name} wide>
        {openPatient && <PatientHistory ctx={ctx} patient={openPatient} />}
      </Modal>
    </div>
  );
}

function PatientHistory({ ctx, patient }) {
  const { appointments, dentists, types } = ctx;
  const history = appointments.filter((a) => a.patientId === patient.id).sort((a, b) => (b.date + b.time).localeCompare(a.date + a.time));
  const next = history.find((a) => ACTIVE_STATUSES.includes(a.status) && a.date >= todayStr());
  const totalPaid = history.reduce((s, a) => s + (Number(a.paidAmount) || 0), 0);

  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 16, fontSize: 13.5 }}>
        <div><b>Celular:</b> {patient.phone || "—"}</div>
        {patient.historyNumber && <div><b>N° de historia:</b> {patient.historyNumber}</div>}
        <div><b>Total pagado histórico:</b> Bs {totalPaid}</div>
        <div style={{ gridColumn: "1 / -1" }}><b>Próxima cita:</b> {next ? `${fmtDateHuman(next.date)} · ${next.time}` : "Ninguna programada"}</div>
      </div>
      {(patient.importedNotes || []).length > 0 && (
        <div style={{ marginBottom: 16 }}>
          <div style={{ fontWeight: 700, fontSize: 13.5, marginBottom: 8 }}>Historial anterior (importado)</div>
          <div style={{ display: "grid", gap: 6 }}>
            {patient.importedNotes.map((n) => (
              <div key={n.id} className="vd-card" style={{ padding: 10, background: "var(--teal-tint)", border: "none" }}>
                <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 2 }}>{n.date ? fmtDateShort(n.date) : "Sin fecha"}</div>
                <div style={{ fontSize: 13 }}>{n.text}</div>
              </div>
            ))}
          </div>
        </div>
      )}
      <div style={{ fontWeight: 700, fontSize: 13.5, marginBottom: 8 }}>Historial de citas</div>
      <div style={{ display: "grid", gap: 8 }}>
        {history.length === 0 && <Empty text="Sin historial todavía." />}
        {history.map((a) => (
          <div key={a.id} className="vd-card" style={{ padding: 12 }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
              <b style={{ fontSize: 13 }}>{fmtDateHuman(a.date)} · {a.time}</b>
              <div style={{ display: "flex", gap: 6 }}>
                {a.priorityApproved && <VimaxPlusBadge />}
                <Badge status={a.status} />
              </div>
            </div>
            <div style={{ fontSize: 12.5, color: "var(--muted)" }}>{dentists.find((d) => d.id === a.dentistId)?.name} · {types.find((t) => t.id === a.typeId)?.name}</div>
            {a.reason && <div style={{ fontSize: 12.5, marginTop: 4 }}><b>Motivo:</b> {a.reason}</div>}
            {a.treatment && <div style={{ fontSize: 12.5 }}><b>Tratamiento:</b> {a.treatment}</div>}
            {a.notes && <div style={{ fontSize: 12.5 }}><b>Notas:</b> {a.notes}</div>}
            {a.paidAmount > 0 && <div style={{ fontSize: 12.5 }}><b>Pagado:</b> Bs {a.paidAmount}</div>}
          </div>
        ))}
      </div>
    </div>
  );
}

function AdminDentists({ ctx }) {
  const { dentists, persist, notify, pushAudit } = ctx;
  const [editing, setEditing] = useState(null);
  const [scheduleFor, setScheduleFor] = useState(null);

  function save(d) {
    const exists = dentists.some((x) => x.id === d.id);
    const list = exists ? dentists.map((x) => x.id === d.id ? d : x) : [...dentists, d];
    persist.dentists(list);
    pushAudit(exists ? "Odontólogo actualizado" : "Odontólogo creado", d.name, "admin");
    notify("Guardado.");
    setEditing(null);
  }

  return (
    <div>
      <div style={{ fontSize: 12.5, color: "var(--muted)", marginBottom: 12 }}>Solo el administrador puede agregar o editar odontólogos. El número completo es privado y solo se muestra al editar.</div>
      <Btn onClick={() => setEditing({ id: uid("d"), name: "", phone: "", active: true })} style={{ marginBottom: 14 }}><Plus size={16} /> Nuevo odontólogo</Btn>
      <div style={{ display: "grid", gap: 8 }}>
        {dentists.map((d) => (
          <div key={d.id} className="vd-card" style={{ padding: 14, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div>
              <div style={{ fontWeight: 700, fontSize: 14 }}>{d.name} {!d.active && <span style={{ color: "var(--muted)", fontWeight: 500 }}>(inactivo)</span>}</div>
              <div style={{ fontSize: 12.5, color: "var(--muted)" }}>{maskPhone(d.phone)}</div>
            </div>
            <div style={{ display: "flex", gap: 8 }}>
              <button className="vd-btn vd-btn-ghost" style={{ padding: "7px 10px" }} onClick={() => setScheduleFor(d)}><Clock size={15} /></button>
              <button className="vd-btn vd-btn-ghost" style={{ padding: "7px 10px" }} onClick={() => setEditing(d)}><Pencil size={15} /></button>
            </div>
          </div>
        ))}
      </div>
      <Modal open={!!editing} onClose={() => setEditing(null)} title={editing?.name ? "Editar odontólogo" : "Nuevo odontólogo"}>
        {editing && <DentistForm dentist={editing} onSave={save} />}
      </Modal>
      <Modal open={!!scheduleFor} onClose={() => setScheduleFor(null)} title={`Horario — ${scheduleFor?.name || ""}`} wide>
        {scheduleFor && <ScheduleEditor ctx={ctx} dentist={scheduleFor} onDone={() => setScheduleFor(null)} />}
      </Modal>
    </div>
  );
}

function DentistForm({ dentist, onSave }) {
  const [name, setName] = useState(dentist.name);
  const [phone, setPhone] = useState(dentist.phone);
  const [active, setActive] = useState(dentist.active);
  const [bio, setBio] = useState(dentist.bio || "");
  const [certificates, setCertificates] = useState(dentist.certificates || []);
  const [newCertTitle, setNewCertTitle] = useState("");
  const [newCertInstitution, setNewCertInstitution] = useState("");
  const [newCertYear, setNewCertYear] = useState("");

  function addCertificate() {
    if (!newCertTitle.trim()) return;
    setCertificates((c) => [...c, { id: uid("cert"), title: newCertTitle.trim(), institution: newCertInstitution.trim(), year: newCertYear.trim() }]);
    setNewCertTitle(""); setNewCertInstitution(""); setNewCertYear("");
  }
  function removeCertificate(id) {
    setCertificates((c) => c.filter((x) => x.id !== id));
  }

  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Field label="Nombre completo"><input className="vd-input" value={name} onChange={(e) => setName(e.target.value)} /></Field>
      <Field label="WhatsApp / teléfono"><input className="vd-input" value={phone} onChange={(e) => setPhone(e.target.value.replace(/[^\d]/g, ""))} /></Field>
      <Field label="Biografía / presentación (se muestra en el sitio público)">
        <textarea className="vd-textarea" rows={3} value={bio} onChange={(e) => setBio(e.target.value)} placeholder="Ej. Odontóloga con experiencia en..." />
      </Field>
      <label style={{ display: "flex", gap: 8, alignItems: "center", fontSize: 13.5 }}>
        <input type="checkbox" checked={active} onChange={(e) => setActive(e.target.checked)} /> Activo (visible para reservas)
      </label>

      <div style={{ borderTop: "1px solid var(--border)", paddingTop: 12 }}>
        <div className="vd-label" style={{ marginBottom: 8 }}>Certificados / cursos (se muestran en su perfil público)</div>
        <div style={{ display: "grid", gap: 6, marginBottom: 10 }}>
          {certificates.map((c) => (
            <div key={c.id} className="vd-card" style={{ padding: 10, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <div style={{ fontWeight: 600, fontSize: 13 }}>{c.title}</div>
                <div style={{ fontSize: 11.5, color: "var(--muted)" }}>{[c.institution, c.year].filter(Boolean).join(" · ")}</div>
              </div>
              <button className="vd-btn vd-btn-danger" style={{ padding: "5px 9px" }} onClick={() => removeCertificate(c.id)}><Trash2 size={13} /></button>
            </div>
          ))}
          {certificates.length === 0 && <div style={{ fontSize: 12.5, color: "var(--muted)" }}>Sin certificados agregados todavía.</div>}
        </div>
        <div style={{ display: "grid", gap: 6 }}>
          <input className="vd-input" placeholder="Nombre del curso/certificado" value={newCertTitle} onChange={(e) => setNewCertTitle(e.target.value)} />
          <div style={{ display: "grid", gridTemplateColumns: "1fr 100px", gap: 6 }}>
            <input className="vd-input" placeholder="Institución (opcional)" value={newCertInstitution} onChange={(e) => setNewCertInstitution(e.target.value)} />
            <input className="vd-input" placeholder="Año" value={newCertYear} onChange={(e) => setNewCertYear(e.target.value.replace(/[^\d]/g, ""))} />
          </div>
          <Btn variant="ghost" onClick={addCertificate}><Plus size={14} /> Agregar certificado</Btn>
        </div>
      </div>

      <Btn disabled={!name.trim() || !phone.trim()} onClick={() => onSave({ ...dentist, name: name.trim(), phone: phone.trim(), active, bio: bio.trim(), certificates })}>Guardar</Btn>
    </div>
  );
}

function ConflictWarning({ conflicts, dentist, note }) {
  if (!conflicts.length) return null;
  return (
    <div style={{ marginTop: 8, fontSize: 12, color: "var(--rose)", background: "#F6E4E6", borderRadius: 8, padding: 10 }}>
      <div style={{ display: "flex", gap: 6, alignItems: "flex-start", marginBottom: 6 }}>
        <AlertTriangle size={14} style={{ flexShrink: 0, marginTop: 2 }} />
        <span>{conflicts.length} cita(s) afectada(s). {note}</span>
      </div>
      <div style={{ display: "grid", gap: 5 }}>
        {conflicts.slice(0, 5).map((c) => (
          <div key={c.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", background: "#fff", borderRadius: 6, padding: "5px 8px" }}>
            <span>{c.patientName} — {fmtDateShort(c.date)} {c.time} · {c.patientPhone}</span>
            <a href={waLink(c.patientPhone, `Hola ${c.patientName}, soy ${dentist.name} de Vimax Dent. Necesito coordinar tu cita del ${fmtDateShort(c.date)} a las ${c.time}.`)} target="_blank" rel="noreferrer" style={{ color: "var(--teal-deep)", fontWeight: 700, whiteSpace: "nowrap" }}>
              WhatsApp
            </a>
          </div>
        ))}
        {conflicts.length > 5 && <div style={{ color: "var(--muted)" }}>…y {conflicts.length - 5} más.</div>}
      </div>
    </div>
  );
}

function ScheduleEditor({ ctx, dentist, onDone }) {
  const { schedules, appointments, config, persist, notify, pushAudit } = ctx;
  const initialProfiles = normalizeProfiles(schedules[dentist.id]);
  const [profiles, setProfiles] = useState(initialProfiles);
  const [selectedId, setSelectedId] = useState((initialProfiles.find((p) => p.active) || initialProfiles[0]).id);
  const [newBlocked, setNewBlocked] = useState("");
  const [savedAt, setSavedAt] = useState(null);
  const [newProfileName, setNewProfileName] = useState("");
  const [creatingProfile, setCreatingProfile] = useState(false);
  const [pendingActivate, setPendingActivate] = useState(null); // profile id awaiting confirmation

  const duration = config.appointmentDurationMin || 30;
  const selected = profiles.find((p) => p.id === selectedId) || profiles[0];

  function updateSelected(patch) {
    setProfiles((ps) => ps.map((p) => p.id === selectedId ? { ...p, ...patch } : p));
    setSavedAt(null);
  }
  function updateDay(i, patch) {
    updateSelected({ days: { ...selected.days, [i]: { ...selected.days[i], ...patch } } });
  }
  function toggleDay(i) {
    const wasEnabled = selected.days[i]?.enabled;
    updateDay(i, { enabled: !wasEnabled, start: selected.days[i]?.start || "08:00", end: selected.days[i]?.end || "17:00" });
  }
  function addBlocked() {
    if (!newBlocked || (selected.blockedDates || []).includes(newBlocked)) return;
    updateSelected({ blockedDates: [...(selected.blockedDates || []), newBlocked].sort() });
    setNewBlocked("");
  }
  function removeBlocked(bd) {
    updateSelected({ blockedDates: (selected.blockedDates || []).filter((x) => x !== bd) });
  }
  function createProfile() {
    if (!newProfileName.trim()) return;
    const p = { id: uid("sch"), name: newProfileName.trim(), active: false, days: emptyDays(), blockedDates: [], specialDates: {} };
    setProfiles((ps) => [...ps, p]);
    setSelectedId(p.id);
    setNewProfileName("");
    setCreatingProfile(false);
    setSavedAt(null);
  }
  function requestActivate(id) {
    if (id === profiles.find((p) => p.active)?.id) return;
    const target = profiles.find((p) => p.id === id);
    const conflicts = appointmentsNotCoveredBy(appointments, dentist.id, target, duration);
    if (conflicts.length > 0) {
      setPendingActivate(id);
    } else {
      activateNow(id);
    }
  }
  function activateNow(id) {
    setProfiles((ps) => ps.map((p) => ({ ...p, active: p.id === id })));
    setSelectedId(id);
    setPendingActivate(null);
    setSavedAt(null);
  }
  function save() {
    persist.schedules({ ...schedules, [dentist.id]: { profiles } });
    pushAudit("Horario actualizado", dentist.name, "admin");
    notify("Horario guardado.");
    setSavedAt(Date.now());
  }

  const dayDisableConflicts = {};
  for (let i = 0; i <= 6; i++) {
    if (selected.active && !selected.days[i]?.enabled) dayDisableConflicts[i] = conflictsOnWeekday(appointments, dentist.id, i);
  }
  const pendingProfile = pendingActivate ? profiles.find((p) => p.id === pendingActivate) : null;
  const pendingConflicts = pendingProfile ? appointmentsNotCoveredBy(appointments, dentist.id, pendingProfile, duration) : [];

  return (
    <div style={{ display: "grid", gap: 16 }}>
      <div>
        <div className="vd-label" style={{ marginBottom: 8 }}>Mis horarios</div>
        <div style={{ display: "grid", gap: 8 }}>
          {profiles.map((p) => (
            <div key={p.id} className="vd-card" style={{ padding: 10, display: "flex", justifyContent: "space-between", alignItems: "center", borderColor: p.id === selectedId ? "var(--teal)" : "var(--border)", cursor: "pointer" }} onClick={() => setSelectedId(p.id)}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ fontWeight: 700, fontSize: 13.5 }}>{p.name}</span>
                {p.active && <span className="vd-badge" style={{ background: "var(--teal-tint)", color: "var(--teal-deep)" }}>Activo</span>}
              </div>
              {!p.active && (
                <button className="vd-btn vd-btn-ghost" style={{ padding: "5px 10px", fontSize: 12 }} onClick={(e) => { e.stopPropagation(); requestActivate(p.id); }}>Usar este horario</button>
              )}
            </div>
          ))}
        </div>
        {creatingProfile ? (
          <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
            <input className="vd-input" placeholder="Ej. Horario de verano" value={newProfileName} onChange={(e) => setNewProfileName(e.target.value)} />
            <Btn variant="ghost" onClick={createProfile}>Crear</Btn>
          </div>
        ) : (
          <button onClick={() => setCreatingProfile(true)} style={{ marginTop: 8, background: "none", border: "none", color: "var(--teal-deep)", fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}>+ Crear nuevo horario</button>
        )}
        {pendingProfile && (
          <div style={{ marginTop: 10 }}>
            <ConflictWarning conflicts={pendingConflicts} dentist={dentist} note={`Estas citas ya no caben en "${pendingProfile.name}". Contacta a los pacientes antes de activarlo:`} />
            <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
              <Btn variant="danger" onClick={() => activateNow(pendingActivate)}>Activar de todas formas</Btn>
              <Btn variant="ghost" onClick={() => setPendingActivate(null)}>Cancelar</Btn>
            </div>
          </div>
        )}
      </div>

      <div style={{ borderTop: "1px solid var(--border)", paddingTop: 14 }}>
        <div style={{ fontSize: 12.5, color: "var(--muted)", marginBottom: 10 }}>Editando: <b>{selected.name}</b> — activa cada día que atiende y define su propio horario.</div>
        <div style={{ display: "grid", gap: 10 }}>
          {WEEKDAY_LABELS.map((lbl, i) => {
            const d = selected.days[i] || { enabled: false, start: "08:00", end: "17:00", breakStart: "", breakEnd: "" };
            const conflicts = dayDisableConflicts[i] || [];
            return (
              <div key={i} className="vd-card" style={{ padding: 12, borderColor: d.enabled ? "var(--teal)" : "var(--border)" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <label style={{ display: "flex", gap: 8, alignItems: "center", fontWeight: 700, fontSize: 14 }}>
                    <input type="checkbox" checked={!!d.enabled} onChange={() => toggleDay(i)} />
                    {lbl}
                  </label>
                  {!d.enabled && <span style={{ fontSize: 12, color: "var(--muted)" }}>No atiende</span>}
                </div>
                {d.enabled && (
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginTop: 10 }}>
                    <Field label="Inicio"><input type="time" className="vd-input" value={d.start} onChange={(e) => updateDay(i, { start: e.target.value })} /></Field>
                    <Field label="Fin"><input type="time" className="vd-input" value={d.end} onChange={(e) => updateDay(i, { end: e.target.value })} /></Field>
                    <Field label="Descanso — inicio (opcional)"><input type="time" className="vd-input" value={d.breakStart} onChange={(e) => updateDay(i, { breakStart: e.target.value })} /></Field>
                    <Field label="Descanso — fin (opcional)"><input type="time" className="vd-input" value={d.breakEnd} onChange={(e) => updateDay(i, { breakEnd: e.target.value })} /></Field>
                  </div>
                )}
                {selected.active && <ConflictWarning conflicts={conflicts} dentist={dentist} note="Si dejas este día sin atención, contacta a estos pacientes:" />}
              </div>
            );
          })}
        </div>

        <Field label="Días bloqueados / vacaciones puntuales">
          <div style={{ display: "flex", gap: 8 }}>
            <input type="date" className="vd-input" value={newBlocked} onChange={(e) => setNewBlocked(e.target.value)} />
            <Btn variant="ghost" onClick={addBlocked}>Agregar</Btn>
          </div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 8 }}>
            {(selected.blockedDates || []).map((bd) => {
              const conflicts = selected.active ? conflictsOnDate(appointments, dentist.id, bd) : [];
              return (
                <div key={bd}>
                  <span className="vd-badge" style={{ background: "var(--teal-tint)", color: "var(--teal-deep)", cursor: "pointer" }} onClick={() => removeBlocked(bd)}>
                    {fmtDateShort(bd)} ✕
                  </span>
                  <ConflictWarning conflicts={conflicts} dentist={dentist} note="No olvides avisarles:" />
                </div>
              );
            })}
          </div>
        </Field>
      </div>

      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <Btn onClick={save}>Guardar horario</Btn>
        {savedAt && <span style={{ fontSize: 13, color: "var(--teal-deep)", fontWeight: 600, display: "flex", alignItems: "center", gap: 6 }}><CheckCircle2 size={16} /> Guardado</span>}
      </div>
    </div>
  );
}

function AdminTypes({ ctx }) {
  const { types, persist, notify, pushAudit } = ctx;
  const [editing, setEditing] = useState(null);

  function save(t) {
    const exists = types.some((x) => x.id === t.id);
    persist.types(exists ? types.map((x) => x.id === t.id ? t : x) : [...types, t]);
    pushAudit(exists ? "Tipo de consulta actualizado" : "Tipo de consulta creado", t.name, "admin");
    notify("Guardado.");
    setEditing(null);
  }
  function toggleActive(t) { save({ ...t, active: !t.active }); }
  function remove(t) {
    persist.types(types.filter((x) => x.id !== t.id));
    pushAudit("Tipo de consulta eliminado", t.name, "admin");
    notify("Eliminado.");
  }

  return (
    <div>
      <Btn onClick={() => setEditing({ id: uid("type"), name: "", active: true })} style={{ marginBottom: 14 }}><Plus size={16} /> Nuevo tipo</Btn>
      <div style={{ display: "grid", gap: 8 }}>
        {types.map((t) => (
          <div key={t.id} className="vd-card" style={{ padding: 14, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontWeight: 600, fontSize: 14 }}>{t.name} {!t.active && <span style={{ color: "var(--muted)", fontWeight: 500 }}>(inactivo)</span>}</span>
            <div style={{ display: "flex", gap: 8 }}>
              <button className="vd-btn vd-btn-ghost" style={{ padding: "6px 10px", fontSize: 12 }} onClick={() => toggleActive(t)}>{t.active ? "Desactivar" : "Activar"}</button>
              <button className="vd-btn vd-btn-ghost" style={{ padding: "6px 9px" }} onClick={() => setEditing(t)}><Pencil size={14} /></button>
              <button className="vd-btn vd-btn-danger" style={{ padding: "6px 9px" }} onClick={() => remove(t)}><Trash2 size={14} /></button>
            </div>
          </div>
        ))}
      </div>
      <Modal open={!!editing} onClose={() => setEditing(null)} title={editing?.name ? "Editar tipo" : "Nuevo tipo de consulta"}>
        {editing && (
          <div style={{ display: "grid", gap: 12 }}>
            <Field label="Nombre"><input className="vd-input" value={editing.name} onChange={(e) => setEditing({ ...editing, name: e.target.value })} /></Field>
            <Btn disabled={!editing.name.trim()} onClick={() => save(editing)}>Guardar</Btn>
          </div>
        )}
      </Modal>
    </div>
  );
}

function AdminPayments({ ctx }) {
  const { appointments, dentists } = ctx;
  const paid = appointments.filter((a) => Number(a.paidAmount) > 0).sort((a, b) => (b.date).localeCompare(a.date));
  const total = paid.reduce((s, a) => s + Number(a.paidAmount), 0);
  const byMonth = {};
  paid.forEach((a) => { const m = a.date.slice(0, 7); byMonth[m] = (byMonth[m] || 0) + Number(a.paidAmount); });

  return (
    <div>
      <div className="vd-card" style={{ padding: 18, marginBottom: 16, background: "var(--teal-tint)", border: "none" }}>
        <div style={{ fontSize: 12.5, color: "var(--muted)" }}>Total registrado</div>
        <div className="vd-serif" style={{ fontSize: 28, fontWeight: 700, color: "var(--ink)" }}>Bs {total}</div>
      </div>
      <div style={{ fontWeight: 700, fontSize: 13.5, marginBottom: 8 }}>Por mes</div>
      <div style={{ display: "grid", gap: 6, marginBottom: 18 }}>
        {Object.keys(byMonth).sort().reverse().map((m) => (
          <div key={m} style={{ display: "flex", justifyContent: "space-between", fontSize: 13.5, padding: "6px 0", borderBottom: "1px solid var(--border)" }}>
            <span>{m}</span><b>Bs {byMonth[m]}</b>
          </div>
        ))}
      </div>
      <div style={{ fontWeight: 700, fontSize: 13.5, marginBottom: 8 }}>Detalle de pagos</div>
      <div style={{ display: "grid", gap: 8 }}>
        {paid.length === 0 && <Empty icon={DollarSign} text="Aún no hay pagos registrados." />}
        {paid.map((a) => (
          <div key={a.id} className="vd-card" style={{ padding: 12, display: "flex", justifyContent: "space-between" }}>
            <div>
              <div style={{ fontWeight: 600, fontSize: 13.5 }}>{a.patientName}</div>
              <div style={{ fontSize: 12, color: "var(--muted)" }}>{fmtDateShort(a.date)} · {dentists.find((d) => d.id === a.dentistId)?.name} · {a.treatment || "—"}</div>
            </div>
            <b style={{ color: "var(--teal-deep)" }}>Bs {a.paidAmount}</b>
          </div>
        ))}
      </div>
    </div>
  );
}

function AdminNotifications({ ctx }) {
  const { notifications, persist } = ctx;
  function markRead(id) { persist.notifications(notifications.map((n) => n.id === id ? { ...n, read: true } : n)); }
  function markAllRead() { persist.notifications(notifications.map((n) => ({ ...n, read: true }))); }
  return (
    <div>
      {notifications.some((n) => !n.read) && <Btn variant="ghost" onClick={markAllRead} style={{ marginBottom: 14 }}>Marcar todas como leídas</Btn>}
      <div style={{ display: "grid", gap: 8 }}>
        {notifications.length === 0 && <Empty icon={Bell} text="Sin notificaciones." />}
        {notifications.map((n) => (
          <div key={n.id} className="vd-card" style={{ padding: 13, opacity: n.read ? 0.6 : 1, cursor: "pointer" }} onClick={() => markRead(n.id)}>
            <div style={{ fontSize: 13.5 }}>{n.text}</div>
            <div style={{ fontSize: 11.5, color: "var(--muted)", marginTop: 4 }}>{new Date(n.at).toLocaleString("es-BO")}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

function AdminConfig({ ctx }) {
  const { config, persist, notify, pushAudit } = ctx;
  const [form, setForm] = useState(config);
  function save() {
    persist.config(form);
    pushAudit("Configuración de clínica actualizada", "", "admin");
    notify("Configuración guardada.");
  }
  return (
    <div className="vd-card" style={{ padding: 20, maxWidth: 520, display: "grid", gap: 12 }}>
      <Field label="Nombre de la clínica"><input className="vd-input" value={form.clinicName} onChange={(e) => setForm({ ...form, clinicName: e.target.value })} /></Field>
      <Field label="Número general (opcional)"><input className="vd-input" value={form.generalPhone} onChange={(e) => setForm({ ...form, generalPhone: e.target.value.replace(/[^\d]/g, "") })} /></Field>
      <Field label="Sobre Vimax Dent"><textarea className="vd-textarea" rows={4} value={form.aboutText} onChange={(e) => setForm({ ...form, aboutText: e.target.value })} /></Field>
      <Field label="Enlace de Google Maps"><input className="vd-input" value={form.locationUrl} onChange={(e) => setForm({ ...form, locationUrl: e.target.value })} /></Field>
      <Field label="Duración real de cada cita (minutos) — cuánto ocupa al odontólogo">
        <select className="vd-select" value={form.appointmentDurationMin} onChange={(e) => setForm({ ...form, appointmentDurationMin: Number(e.target.value) })}>
          {[15, 20, 25, 30, 40, 45, 60, 90].map((m) => <option key={m} value={m}>{m} min</option>)}
        </select>
      </Field>
      <Field label="Cada cuánto se muestran horarios (minutos)">
        <select className="vd-select" value={form.slotIntervalMin} onChange={(e) => setForm({ ...form, slotIntervalMin: Number(e.target.value) })}>
          {[10, 15, 20, 30, 60].map((m) => <option key={m} value={m}>{m} min</option>)}
        </select>
        <div style={{ fontSize: 11.5, color: "var(--muted)", marginTop: 4 }}>
          Ej: si la cita dura 60 min y esto está en 30 min, un paciente puede empezar a las 4:00 o 4:30 — pero si alguien
          reserva 4:00, el próximo horario libre real será 5:00 (no 4:30), porque el odontólogo sigue ocupado.
        </div>
      </Field>
      <Field label="Ventana mínima para cancelar/reprogramar (horas)">
        <input type="number" className="vd-input" value={form.cancelWindowHours} onChange={(e) => setForm({ ...form, cancelWindowHours: Number(e.target.value) })} />
      </Field>
      <Btn onClick={save}>Guardar configuración</Btn>
    </div>
  );
}

