function parsePatientImportText(text) {
  return text
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      // Formato esperado (pegado desde Word/Excel): Nombre, Fecha, Número
      // de historia — separado por tabulaciones, comas o 2+ espacios.
      let cols = line.split("\t");
      if (cols.length < 2) cols = line.split(/ {2,}/);
      if (cols.length < 2) cols = line.split(",");
      cols = cols.map((c) => c.trim()).filter((c) => c !== "");
      const name = cols[0] || "";
      const date = cols[1] || "";
      const historyNumber = cols[2] || "";
      const note = cols.slice(3).join(" — ");
      return { name, date, historyNumber, note };
    })
    .filter((r) => r.name);
}

function PatientImportModal({ ctx, dentistId, onDone }) {
  const { patients, persist, notify, pushAudit } = ctx;
  const [text, setText] = useState("");
  const rows = parsePatientImportText(text);

  function confirmImport() {
    let list = [...patients];
    let created = 0, updated = 0;
    rows.forEach((r) => {
      let p = null;
      if (r.historyNumber) p = list.find((x) => x.historyNumber && x.historyNumber === r.historyNumber);
      if (!p) p = list.find((x) => x.name.trim().toLowerCase() === r.name.trim().toLowerCase());
      const note = (r.date || r.note) ? { id: uid("note"), date: r.date, text: r.note || "Paciente importado" } : null;
      if (p) {
        list = list.map((x) => x.id === p.id ? {
          ...x,
          historyNumber: x.historyNumber || r.historyNumber,
          primaryDentistId: x.primaryDentistId || dentistId,
          importedNotes: note ? [...(x.importedNotes || []), note] : (x.importedNotes || []),
        } : x);
        updated++;
      } else {
        const np = { id: uid("pat"), name: r.name, phone: "", historyNumber: r.historyNumber, createdAt: new Date().toISOString(), primaryDentistId: dentistId, importedNotes: note ? [note] : [] };
        list = [...list, np];
        created++;
      }
    });
    persist.patients(list);
    pushAudit("Pacientes importados", `${created} nuevos, ${updated} actualizados`, "odontólogo");
    notify(`Importados: ${created} nuevos, ${updated} ya existentes actualizados.`);
    onDone();
  }

  return (
    <div style={{ display: "grid", gap: 12 }}>
      <div style={{ fontSize: 12.5, color: "var(--muted)", lineHeight: 1.5 }}>
        Copia las filas de tu lista de Word o Excel con <b>nombre completo, fecha y número de historia</b> (en ese
        orden) y pégalas aquí — una línea por paciente. Cuando esa persona agende una cita más adelante, el sistema la
        va a reconocer por su nombre y no la va a duplicar como paciente nuevo.
      </div>
      <textarea
        className="vd-textarea"
        rows={8}
        placeholder={"Ana Pérez\t15/03/2024\t0245\nJuan Gómez\t20/01/2024\t0246"}
        value={text}
        onChange={(e) => setText(e.target.value)}
      />
      {rows.length > 0 && (
        <div>
          <div style={{ fontWeight: 700, fontSize: 12.5, marginBottom: 6 }}>Vista previa ({rows.length} paciente{rows.length !== 1 ? "s" : ""})</div>
          <div className="vd-scroll" style={{ maxHeight: 220, overflowY: "auto", display: "grid", gap: 6 }}>
            {rows.map((r, i) => (
              <div key={i} className="vd-card" style={{ padding: 10, fontSize: 12.5 }}>
                <b>{r.name}</b>{r.date ? ` · ${r.date}` : ""}{r.historyNumber ? ` · N° historia: ${r.historyNumber}` : ""}{r.note ? ` · ${r.note}` : ""}
              </div>
            ))}
          </div>
        </div>
      )}
      <Btn disabled={rows.length === 0} onClick={confirmImport}>Importar {rows.length > 0 ? `(${rows.length})` : ""}</Btn>
    </div>
  );
}

function DentistPatients({ ctx, dentistId }) {
  const { appointments, patients } = ctx;
  const [openPatient, setOpenPatient] = useState(null);
  const [importing, setImporting] = useState(false);
  const patientIds = new Set(appointments.filter((a) => a.dentistId === dentistId).map((a) => a.patientId));
  const mine = patients.filter((p) => patientIds.has(p.id) || p.primaryDentistId === dentistId);
  return (
    <div>
      <Btn variant="ghost" style={{ marginBottom: 14 }} onClick={() => setImporting(true)}><Plus size={16} /> Importar pacientes (pegar desde Word/Excel)</Btn>
      <div style={{ display: "grid", gap: 8 }}>
        {mine.length === 0 && <Empty icon={Users} text="Todavía no tienes pacientes atendidos." />}
        {mine.map((p) => (
          <div key={p.id} className="vd-card" style={{ padding: 14, cursor: "pointer" }} onClick={() => setOpenPatient(p)}>
            <div style={{ fontWeight: 700, fontSize: 14 }}>{p.name}</div>
            <div style={{ fontSize: 12.5, color: "var(--muted)" }}>{[p.historyNumber ? `N° historia: ${p.historyNumber}` : null, p.phone || null].filter(Boolean).join(" · ")}</div>
          </div>
        ))}
      </div>
      <Modal open={!!openPatient} onClose={() => setOpenPatient(null)} title={openPatient?.name} wide>
        {openPatient && <PatientHistory ctx={ctx} patient={openPatient} />}
      </Modal>
      <Modal open={importing} onClose={() => setImporting(false)} title="Importar pacientes" wide>
        <PatientImportModal ctx={ctx} dentistId={dentistId} onDone={() => setImporting(false)} />
      </Modal>
    </div>
  );
}

/* ============================================================
   NOTA DE ARQUITECTURA (no visible al usuario final, referencia
   para una futura migración a backend real):

   - Persistencia actual: window.storage (clave-valor compartida
     entre todos los usuarios del artifact). Simula una base de
     datos, pero no ofrece transacciones reales ni bloqueo a nivel
     de fila: la prevención de choques se resuelve leyendo el
     estado más reciente justo antes de escribir (withFreshAppointments)
     y verificando solapamiento — reduce drásticamente el riesgo de
     doble reserva pero no lo elimina al 100% bajo concurrencia alta
     simultánea, algo que sí exige un backend con transacciones
     (p. ej. Postgres + constraint EXCLUDE, o una cola de escritura).
   - Autenticación: usuarios y contraseñas en texto plano dentro del
     storage compartido, sin hashing ni JWT — válido solo como
     demostración. Un backend real necesita bcrypt/argon2, sesiones
     firmadas y limitación de intentos.
   - WhatsApp Business: se usan enlaces wa.me (mensajería manual).
     La API oficial de WhatsApp Business requiere un servidor con
     credenciales (Meta), colas de mensajes y webhooks — no es
     alcanzable desde un artifact de frontend puro.
   - Chatbot: usa fetch directo a la API de Anthropic desde el
     cliente, sin backend intermedio; es aceptable para una demo
     pero en producción conviene un proxy backend para no exponer
     lógica de negocio ni límites de uso.
   ============================================================ */
